async function main() {
  if (!process.argv.includes("--yes")) {
    throw new Error(
      "Refusing to run without --yes — this writes to the LIVE delivery-app-syria-2026 project."
    );
  }
  if (process.env.FIRESTORE_EMULATOR_HOST) {
    throw new Error(
      "FIRESTORE_EMULATOR_HOST is set — this script seeds real reference data on the live " +
        "project, not emulator/demo data. Unset it before running."
    );
  }

  admin.initializeApp({ projectId: PROJECT_ID });
  const db = admin.firestore();

  for (const [index, neighborhood] of NEIGHBORHOODS.entries()) {
    await db.collection("neighborhoods").doc(neighborhood.id).set({
      nameEn: neighborhood.nameEn,
      nameAr: neighborhood.nameAr,
      cityId: neighborhood.cityId,
      enabled: neighborhood.enabled,
      order: neighborhood.order,
      ochaPcode: neighborhood.ochaPcode,
    });
    if ((index + 1) % 25 === 0 || index === NEIGHBORHOODS.length - 1) {
      console.log(`Seeded ${index + 1}/${NEIGHBORHOODS.length}`);
    }
  }
}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error(error);
    process.exit(1);
  });
